package com.bank.apigw.services;

import java.util.logging.Logger;

// A backend service (account/payment/card). The gateway calls it synchronously.
public class BackendService {
    private static final Logger log = Logger.getLogger(BackendService.class.getName());
    private final String name;
    private boolean down = false;

    public BackendService(String name) { this.name = name; }
    public void simulateOutage(boolean down) { this.down = down; }

    public String fetch(String accountId) {
        if (down) throw new ServiceException(name + " unavailable");
        log.info(() -> "SYNC call to " + name + " for " + accountId);
        return name + "-data";
    }
    public String getName() { return name; }
}
