package com.bank.apigw.discovery;

import com.bank.apigw.services.BackendService;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

// Service discovery + client-side load balancing over healthy instances.
public class ServiceRegistry {
    private final Map<String, List<BackendService>> instances = new HashMap<>();
    private final AtomicInteger counter = new AtomicInteger(0);

    public void register(String name, BackendService instance) {
        instances.computeIfAbsent(name, k -> new ArrayList<>()).add(instance);
    }
    public BackendService choose(String name) {   // round-robin load balance
        List<BackendService> list = instances.getOrDefault(name, List.of());
        if (list.isEmpty()) throw new IllegalStateException("No instance for " + name);
        return list.get(Math.abs(counter.getAndIncrement() % list.size()));
    }
}
