package com.bank.apigw.gateway;

import com.bank.apigw.discovery.ServiceRegistry;
import com.bank.apigw.services.BackendService;
import com.bank.apigw.services.ServiceException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// API Gateway pattern: single synchronous entry point. Auth once, discover,
// load-balance, aggregate, and wrap each call in a circuit breaker.
public class ApiGateway {
    private static final Logger log = Logger.getLogger(ApiGateway.class.getName());
    private final ServiceRegistry registry;

    public ApiGateway(ServiceRegistry registry) { this.registry = registry; }

    public Map<String, String> dashboard(String jwt, String accountId) {
        if (jwt == null || jwt.isBlank()) throw new SecurityException("Missing JWT"); // auth once
        log.info(() -> "Gateway authenticated + aggregating for " + accountId);
        Map<String, String> response = new LinkedHashMap<>();
        response.put("account", callWithBreaker("account-service", accountId));
        response.put("payment", callWithBreaker("payment-service", accountId));
        response.put("card", callWithBreaker("card-service", accountId));   // may fall back
        return response;
    }

    // Circuit-breaker style: fail fast with a fallback instead of hanging.
    private String callWithBreaker(String serviceName, String accountId) {
        try {
            BackendService instance = registry.choose(serviceName);  // discovery + LB
            return instance.fetch(accountId);
        } catch (ServiceException ex) {
            log.warning(() -> serviceName + " failed — serving fallback: " + ex.getMessage());
            return serviceName + "-UNAVAILABLE";
        }
    }
}
