package com.bank.apigw;

import com.bank.apigw.discovery.ServiceRegistry;
import com.bank.apigw.gateway.ApiGateway;
import com.bank.apigw.services.BackendService;
import java.util.logging.Logger;

public class ApiGatewaySyncDemo {
    private static final Logger log = Logger.getLogger(ApiGatewaySyncDemo.class.getName());

    public static void main(String[] args) {
        ServiceRegistry registry = new ServiceRegistry();
        registry.register("account-service", new BackendService("account-service"));
        registry.register("payment-service", new BackendService("payment-service"));
        BackendService card = new BackendService("card-service");
        registry.register("card-service", card);

        ApiGateway gateway = new ApiGateway(registry);

        log.info("=== Single synchronous call → gateway aggregates three services ===");
        log.info("Dashboard: " + gateway.dashboard("valid-jwt", "SAV2001"));

        log.info("=== Card service down → gateway fails fast with fallback ===");
        card.simulateOutage(true);
        log.info("Dashboard: " + gateway.dashboard("valid-jwt", "SAV2001"));
    }
}
